import { existsSync, readFileSync } from 'node:fs';
import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join, relative, resolve, sep } from 'node:path';
import { performance } from 'node:perf_hooks';
import { bundle, canonical, inside } from './bundle.js';
import { buildClientAccess } from './client-access.js';
import { Diagnostics } from './diagnostics.js';
import { computeBuildId, computeDepsHash, computeIslandsHash, gzipSize, islandPrefix, sha384Integrity, } from './hashing.js';
import { install } from './install.js';
import { CLIENT_DIR, GLOBAL_STYLESHEET, islandEntryPath, islandStylesheetPath, outPath, } from './layout.js';
import { checkClientOutput } from './limits.js';
import { collectLocalFiles, packageManagerFileProblems, runtimeImports } from './local-files.js';
import { findLockfile, lockfileKind, validateLockfile, validateRegistries, validateRegistryHosts, } from './lockfile.js';
import { dependencySpecs, readPackageJson, validatePackageJson } from './package-json.js';
import { checkDuplicateReact, checkPeerRanges, checkReactVersions, reactPackageDirs, readReactInfo, scanRemovedApis, } from './react.js';
